import{_ as u,C as a,o as g,c as b,j as t,a as s,E as o,a8 as y}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/tNAV259UhCM-640.webp",f="/schedule-dashboard/thumbs/yt/tNAV259UhCM-1280.webp",n="/schedule-dashboard/thumbs/yt/TyPpSRXGhbc-640.webp",v="/schedule-dashboard/thumbs/yt/TyPpSRXGhbc-1280.webp",i="/schedule-dashboard/thumbs/yt/cSz7aL2nl2U-640.webp",k="/schedule-dashboard/thumbs/yt/cSz7aL2nl2U-1280.webp",l="/schedule-dashboard/thumbs/yt/6qkzlT962es-640.webp",_="/schedule-dashboard/thumbs/yt/6qkzlT962es-1280.webp",h="/schedule-dashboard/thumbs/yt/BIhiYL4U9_M-640.webp",A="/schedule-dashboard/thumbs/yt/BIhiYL4U9_M-1280.webp",p="/schedule-dashboard/thumbs/yt/3wj6sgbi1YA-640.webp",S="/schedule-dashboard/thumbs/yt/3wj6sgbi1YA-1280.webp",c="/schedule-dashboard/thumbs/yt/9WiBJRO84yY-640.webp",L="/schedule-dashboard/thumbs/yt/9WiBJRO84yY-1280.webp",w="/schedule-dashboard/thumbs/yt/E3KbFLAGD6A-640.webp",I="/schedule-dashboard/thumbs/yt/E3KbFLAGD6A-1280.webp",V=JSON.parse('{"title":"AI Digest · Sat 10 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-10","routine":"digest"},"relativePath":"digest/2026-10-10.md","filePath":"digest/[date].md"}'),C={name:"digest/2026-10-10.md"},T=r+" 640w, "+f+" 1280w",x=n+" 640w, "+v+" 1280w",P=i+" 640w, "+k+" 1280w",U=l+" 640w, "+_+" 1280w",M=h+" 640w, "+A+" 1280w",R=p+" 640w, "+S+" 1280w",B=c+" 640w, "+L+" 1280w",z=w+" 640w, "+I+" 1280w",G={id:"ai-digest-·-sat-10-oct-2026",tabindex:"-1"};function Y(q,e,O,N,E,D){const m=a("Badge"),d=a("DayFilter");return g(),b("div",null,[t("h1",G,[e[0]||(e[0]=s("AI Digest · Sat 10 Oct 2026 ",-1)),o(m,{type:"tip",text:"8"}),e[1]||(e[1]=s()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sat-10-oct-2026","aria-label":'Permalink to "AI Digest · Sat 10 Oct 2026 <Badge type="tip" text="8" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"}," · run date Sat 10 Oct 2026 · 8 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer digest — Sat 10 Oct 2026 (IST)")]),t("p",null,`The freshest talks today are Amazon AGI's GPU data-pipeline teardown and Snorkel/Berkeley's $500 finance-agent RL run. Both are full of real numbers on topics we haven't seen much. Sentry's "Stop Prompting" has a genuinely new angle (getting agents to write linters) on a familiar topic. Merge's context graph, G2i's anti-slop talk and Oracle's memory layer are mostly repeats; Oracle has now given three agent-memory talks.`)],-1)),o(d),e[5]||(e[5]=y('<div class="grid cards2"><article class="it full" id="v-tNAV259UhCM" data-title="From 15% to 90% GPU Utilization: Fix the Data Pipeline, Not the Model" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=tNAV259UhCM" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=tNAV259UhCM" target="_blank" rel="noopener">From 15% to 90% GPU Utilization: Fix the Data Pipeline, Not the Model</a></h3><div class="meta">Tarun Sunkaraneni, Amazon AGI · 10 Oct, 7:00 AM IST · 17:01</div><p class="note">No repeat flag. This is the first data-loading/throughput talk in the history, with step-by-step numbers.</p><p class="note">The problem:</p><p class="note">Fixes, one at a time:</p><p class="note">At scale:</p><p class="note">Verdict: worth watching. It&#39;s the most concrete talk today; if short on time, start at <a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=318s" target="_blank" rel="noopener">5:18</a>.</p><ul><li><strong>CPU work starves the GPU:</strong> Multimodal preprocessing (PIL resize/normalize, audio cropping) is CPU-heavy. Clusters have far more CPUs than GPUs, but the GPU is still the part left idle. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=116s" target="_blank" rel="noopener">1:56</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=157s" target="_blank" rel="noopener">2:37</a>)</li><li><strong>Wait-time ratio:</strong> He measures (data prep + transfer) ÷ (prep + transfer + train). The baseline spends 85% of its time waiting on data, so GPU utilization is only 15%. The target is 90%. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=157s" target="_blank" rel="noopener">2:37</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=217s" target="_blank" rel="noopener">3:37</a>)</li><li><strong>Baseline:</strong> A Qwen3-VL-style model is trained on JSONL with images in S3, feeding Megatron data-parallel ranks. Serial fetching for a 256-item batch means a 15–20 s train step waits on more than 100 s of data loading, and the flame graph is mostly S3 loads. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=318s" target="_blank" rel="noopener">5:18</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=393s" target="_blank" rel="noopener">6:33</a>)</li><li><strong>Concurrency matched to the bottleneck:</strong> asyncio handles the IO-bound image fetches and Ray actors handle CPU processing. Threads only help for ops that release the GIL (HF tokenizers, PIL transforms, some pandas). Per-batch fetch time drops to about 40 s, a 25% speedup. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=430s" target="_blank" rel="noopener">7:10</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=544s" target="_blank" rel="noopener">9:04</a>)</li><li><strong>Prefetching:</strong> A background thread keeps a queue ahead of the trainer, so data fetch time per batch is close to 0 s. The costs: checkpoint/resume gets trickier and there&#39;s a cold-start fill period. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=544s" target="_blank" rel="noopener">9:04</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=635s" target="_blank" rel="noopener">10:35</a>)</li><li><strong>Zero-copy with Ray&#39;s object store:</strong> Each sample (megabytes of image tensors) was pickled worker→coordinator→trainer and could cause OOMs. Passing object refs instead takes the wait ratio from 85% to 20%. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=635s" target="_blank" rel="noopener">10:35</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=767s" target="_blank" rel="noopener">12:47</a>)</li><li><strong>NIC bottleneck:</strong> With 4× DP ranks, 200 data streams and 4× batch size, the wait ratio went back up. Ray places workers on the same node by default, which saturates that node&#39;s network card. Spread scheduling plus zero-copy retrieval did nothing at small scale but together gave +50% throughput at scale. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=767s" target="_blank" rel="noopener">12:47</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=935s" target="_blank" rel="noopener">15:35</a>)</li><li><strong>Lessons:</strong> Fixing one bottleneck exposes the next (throughput → wait time → memory → retrieval cost). Test configs at several scales, and profile the baseline first. (<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=935s" target="_blank" rel="noopener">15:35</a>–<a href="https://www.youtube.com/watch?v=tNAV259UhCM&amp;t=993s" target="_blank" rel="noopener">16:33</a>)</li></ul></div></article><article class="it full" id="v-TyPpSRXGhbc" data-title="Small Models, Big Results: Training a Finance Agent for Under $500" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=TyPpSRXGhbc" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=TyPpSRXGhbc" target="_blank" rel="noopener">Small Models, Big Results: Training a Finance Agent for Under $500</a></h3><div class="meta">Charles (research scientist), Snorkel AI with UC Berkeley Sky Computing Lab · 10 Oct, 6:00 AM IST · 17:15</div><p class="note">No repeat flag. It&#39;s a full RL recipe with costs and ablations.</p><p class="note">Headline result:</p><p class="note">How the data was built:</p><p class="note">Training setup:</p><p class="note">Results and ablations:</p><p class="note">Verdict: worth watching. The last 2.5 minutes from <a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=880s" target="_blank" rel="noopener">14:40</a> are eval-axis philosophy and a grants/hiring pitch.</p><ul><li><strong>4B beats 235B:</strong> An RL-trained Qwen3-4B gets about 60% pass@1 on financial tasks, against 51% for Qwen3-235B. Scripts and synthetic data are open on GitHub. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=149s" target="_blank" rel="noopener">2:29</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=206s" target="_blank" rel="noopener">3:26</a>)</li><li><strong>FinQA from 10-Ks:</strong> SEC 10-K filings were pulled from EDGAR and Qwen3-30B extracted about 6,900 SQL tables, with one QA pair per table built from an expert question taxonomy. Verification has three layers: programmatic lineage/column checks, independent agent review, then expert manual review. The split is 4,000 train / 500 val / 290 held-out, with no company appearing in more than one split. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=295s" target="_blank" rel="noopener">4:55</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=431s" target="_blank" rel="noopener">7:11</a>)</li><li><strong>Frontier failure modes:</strong> Schema hallucination (made-up tables/columns), context flooding (SELECT \\*), and poor error recovery (the 235B model retried the same failed strategy). The same issues showed up in their insurance-underwriting work. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=431s" target="_blank" rel="noopener">7:11</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=488s" target="_blank" rel="noopener">8:08</a>)</li><li><strong>rLLM + GRPO:</strong> Berkeley&#39;s rLLM framework works with any agent framework through a decorator, with near-zero code changes. It has GRPO and other RL algorithms built in. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=488s" target="_blank" rel="noopener">8:08</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=544s" target="_blank" rel="noopener">9:04</a>)</li><li><strong>Cost breakdown:</strong> A ReAct agent with table tools, binary correctness reward from a GPT-5 nano judge (reference-based), about 1,000 concurrent environments, 8× H100. Total under $500: about $420 compute and $40 for the judge API. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=544s" target="_blank" rel="noopener">9:04</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=621s" target="_blank" rel="noopener">10:21</a>)</li><li><strong>Generalizes, doesn&#39;t erode:</strong> Base accuracy more than doubled. Gains carried over to a multi-table set (2–5 tables, 1,000/120/80) without any multi-table training, and BFCL general tool-calling scores went up slightly. (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=621s" target="_blank" rel="noopener">10:21</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=754s" target="_blank" rel="noopener">12:34</a>)</li><li><strong>Simpler won twice:</strong> Training only on simple single-table data beat both mixtures and a single→multi curriculum. A binary reward beat an expert-designed weighted rubric with intermediate rewards. His takeaway: &quot;the bottleneck was never reasoning depth, it was tool use.&quot; (<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=754s" target="_blank" rel="noopener">12:34</a>–<a href="https://www.youtube.com/watch?v=TyPpSRXGhbc&amp;t=844s" target="_blank" rel="noopener">14:04</a>)</li></ul></div></article><article class="it full" id="v-cSz7aL2nl2U" data-title="Why Your Company Needs a Context Graph" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=cSz7aL2nl2U" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=cSz7aL2nl2U" target="_blank" rel="noopener">Why Your Company Needs a Context Graph</a></h3><div class="meta">Gil Feig, Merge · 10 Oct, 5:00 AM IST · 15:11</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 9 times before · 🔁 Repeat: &#39;agent memory&#39; — seen 6 times before</div><p class="note">New here: a concrete rule for when to use a cached copy versus a live lookup (freshness SLAs) and a provenance checklist. The rest is familiar architecture.</p><p class="note">What and why:</p><p class="note">How to select context:</p><p class="note">Traceability:</p><p class="note">Verdict: skim from <a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=195s" target="_blank" rel="noopener">3:15</a> to about <a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=804s" target="_blank" rel="noopener">13:24</a>; everything from <a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=862s" target="_blank" rel="noopener">14:22</a> is a Merge product pitch.</p><ul><li><strong>Company brain (repeat):</strong> The context graph combines third-party data (NetSuite, Jira), structured context, memories and skills. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=138s" target="_blank" rel="noopener">2:18</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=195s" target="_blank" rel="noopener">3:15</a>)</li><li><strong>Where live MCP lookups break:</strong> &quot;Why was customer A upset?&quot; works over Zendesk MCP. &quot;Which customers were upset last year?&quot; means paging 100 tickets at a time until it times out. Vendors have no reason to offer semantic endpoints, so you sync a copy into a vector DB and keep live MCP for point lookups and actions (e.g. Stripe). (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=195s" target="_blank" rel="noopener">3:15</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=356s" target="_blank" rel="noopener">5:56</a>)</li><li><strong>Router + summarizer:</strong> A router sends the prompt to the right place, and a summarizer merges synced and live results so raw dumps never reach the agent. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=356s" target="_blank" rel="noopener">5:56</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=407s" target="_blank" rel="noopener">6:47</a>)</li><li><strong>Skills first (repeat):</strong> What &quot;upset&quot; means is company-specific. One company may count tickets, another may check Qualtrics surveys first. So the agent checks skills and memory before fetching data. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=407s" target="_blank" rel="noopener">6:47</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=515s" target="_blank" rel="noopener">8:35</a>)</li><li><strong>Four tiers and their costs:</strong> Prompt/skills/memory; live API calls (cheaper, easier); cached/synced data (needed for semantic queries but expensive and goes stale); and &quot;derived context&quot;, i.e. stored summaries so common questions aren&#39;t re-fetched. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=515s" target="_blank" rel="noopener">8:35</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=607s" target="_blank" rel="noopener">10:07</a>)</li><li><strong>Selection flowchart:</strong> Check for a skill/memory match first. Then use the cache if it&#39;s within your freshness SLA, otherwise call the live API. Loop until there&#39;s enough context, optionally write a memory, then respond. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=607s" target="_blank" rel="noopener">10:07</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=681s" target="_blank" rel="noopener">11:21</a>)</li><li><strong>Provenance checklist:</strong> Record where and when data was fetched, under what ID and scopes, who accessed it, with what permissions, whether it was transformed, and what invalidates it (e.g. older than a month). In the Acme example he caps live ticket pulls at 5 to avoid timeouts. (<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=681s" target="_blank" rel="noopener">11:21</a>–<a href="https://www.youtube.com/watch?v=cSz7aL2nl2U&amp;t=804s" target="_blank" rel="noopener">13:24</a>)</li></ul></div></article><article class="it full" id="v-6qkzlT962es" data-title="Generation Is Cheap, Review Is Expensive: How to Stop Shipping AI Slop" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=6qkzlT962es" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+U+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=6qkzlT962es" target="_blank" rel="noopener">Generation Is Cheap, Review Is Expensive: How to Stop Shipping AI Slop</a></h3><div class="meta">Gabriel Martinez, G2i · 10 Oct, 1:30 AM IST · 17:17</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 7 times before</div><p class="note">New here: little. It&#39;s an opinion essay with no data. The fresh bits are &quot;diagrams as a compressed review surface&quot; and the convention-over-configuration argument for agents.</p><p class="note">The argument:</p><p class="note">What to do instead:</p><p class="note">Verdict: skim from <a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=743s" target="_blank" rel="noopener">12:23</a> for the ~3 minutes on diagrams and conventions; skip the rest if you&#39;ve seen the earlier code-validation talks.</p><ul><li><strong>Definition:</strong> Slop is &quot;output that looks finished before the thinking is finished.&quot; The danger is less a bad machine choice than the engineer never noticing there was a choice to make. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=39s" target="_blank" rel="noopener">0:39</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=114s" target="_blank" rel="noopener">1:54</a>)</li><li><strong>Lines spent (repeat):</strong> He cites Dijkstra&#39;s &quot;lines spent, not lines produced&quot;. Agents don&#39;t rescue a big ball of mud, they make it bigger faster, and the result is bloated B2B-style UX. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=227s" target="_blank" rel="noopener">3:47</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=337s" target="_blank" rel="noopener">5:37</a>)</li><li><strong>Prototype illusion:</strong> Stakeholders take an hour-long vibe-coded prototype as proof the hard part is done. He quotes SQLite&#39;s creator: a PR isn&#39;t free, it&#39;s a request for 25 years of maintenance. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=337s" target="_blank" rel="noopener">5:37</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=444s" target="_blank" rel="noopener">7:24</a>)</li><li><strong>Bad incentives (repeat):</strong> Pressure to merge fast leads to unreviewed merges (he admits doing it). Multi-thousand-line PRs can&#39;t really be reviewed, and 10 bullets of scope come back as a 20-page doc. &quot;Generation is cheap, evaluation is expensive.&quot; (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=444s" target="_blank" rel="noopener">7:24</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=632s" target="_blank" rel="noopener">10:32</a>)</li><li><strong>Compressed review surfaces:</strong> Diagrams of service boundaries, data flows, state transitions and failure modes, plus declarative code that pushes implementation detail to the leaves, so humans review the shape of the system. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=743s" target="_blank" rel="noopener">12:23</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=799s" target="_blank" rel="noopener">13:19</a>)</li><li><strong>Conventions over choices:</strong> Agents produce five plausible patterns in five styles unless conventions narrow the options. Rails is his example: he came back after 4 years and the same patterns still held. Ecosystems with one right way work better for agents. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=799s" target="_blank" rel="noopener">13:19</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=932s" target="_blank" rel="noopener">15:32</a>)</li><li><strong>ORC pitch:</strong> G2i&#39;s ORC builds planning, review, adversarial checks and context management into the workflow. No specifics or results are given. (<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=932s" target="_blank" rel="noopener">15:32</a>–<a href="https://www.youtube.com/watch?v=6qkzlT962es&amp;t=1008s" target="_blank" rel="noopener">16:48</a>)</li></ul></div></article><article class="it full" id="v-BIhiYL4U9_M" data-title="From Context to Memory: Your Agents Need a Real Memory Layer" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=BIhiYL4U9_M" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=BIhiYL4U9_M" target="_blank" rel="noopener">From Context to Memory: Your Agents Need a Real Memory Layer</a></h3><div class="meta">Anders Swanson, Oracle · 10 Oct, 12:00 AM IST · 18:20</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 6 times before (and Oracle&#39;s third memory talk, after Kay Malcolm on 14 Sep and Ignacio Martinez on 18 Sep)</div><p class="note">New here: the write-path order (redact before embedding) and a clear list of memory failure modes. The framing and memory types are well-worn.</p><p class="note">Familiar ground:</p><p class="note">The concrete parts:</p><p class="note">Verdict: skim from <a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=744s" target="_blank" rel="noopener">12:24</a> for the failure modes and feedback loop; the rest repeats earlier memory talks.</p><ul><li><strong>Context windows aren&#39;t memory (repeat):</strong> Bigger windows lose the useful signal to compaction. Markdown scratchpads and grep don&#39;t scale to multi-tenant setups, and &quot;you&#39;re going to be building your own database.&quot; (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=57s" target="_blank" rel="noopener">0:57</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=166s" target="_blank" rel="noopener">2:46</a>)</li><li><strong>Converging pattern (repeat):</strong> Formation, hybrid recall, consolidation, time-awareness, feedback and governance. Memory types are episodic, semantic, procedural and working state. (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=166s" target="_blank" rel="noopener">2:46</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=276s" target="_blank" rel="noopener">4:36</a>) and (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=371s" target="_blank" rel="noopener">6:11</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=443s" target="_blank" rel="noopener">7:23</a>)</li><li><strong>Storage schema:</strong> ID, content, JSON tags, vector embedding plus vector index, full-text index, graph links between memories, temporal validity/last-used, and audit events (who created and used it). (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=443s" target="_blank" rel="noopener">7:23</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=497s" target="_blank" rel="noopener">8:17</a>)</li><li><strong>Write path order:</strong> Redact PII and secrets first, before embedding or enrichment. Then enrich, scope (agent/team/org), embed, and link an &quot;episode&quot; (the transcript slice that produced it) for provenance. (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=497s" target="_blank" rel="noopener">8:17</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=604s" target="_blank" rel="noopener">10:04</a>)</li><li><strong>Hybrid recall (repeat):</strong> Vector, keyword, entity, graph and feedback branches with tunable weights, fused into a top-K &quot;context card&quot; that shows per-branch scores. Facts can use exact-ID match instead of similarity. (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=604s" target="_blank" rel="noopener">10:04</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=725s" target="_blank" rel="noopener">12:05</a>)</li><li><strong>Failure modes:</strong> Stale memories (e.g. switching from npm to another build system), bad scoping (seeing another user&#39;s history), poisoned memory from prompt injection, conflicting memories that both rank high, over-recall crowding the context, leakage, and silent drift that appears at 50k–1M records. (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=744s" target="_blank" rel="noopener">12:24</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=925s" target="_blank" rel="noopener">15:25</a>)</li><li><strong>Feedback closes the loop:</strong> Track whether each retrieved memory was helpful, stale, irrelevant or harmful, and use that to promote or demote it. (<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=925s" target="_blank" rel="noopener">15:25</a>–<a href="https://www.youtube.com/watch?v=BIhiYL4U9_M&amp;t=978s" target="_blank" rel="noopener">16:18</a>)</li></ul></div></article><article class="it full" id="v-3wj6sgbi1YA" data-title="Designing CLIs for Agents, Not Humans" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=3wj6sgbi1YA" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=3wj6sgbi1YA" target="_blank" rel="noopener">Designing CLIs for Agents, Not Humans</a></h3><div class="meta">Pedro Lopez, Airbyte · 9 Oct, 10:30 PM IST · 18:20</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 9 times before</div><p class="note">New here: the CLI half (design rules for agent callers) and specific MCP client gaps: Claude Desktop doesn&#39;t support URL-mode elicitation, and Claude limits descriptions to 2 KB.</p><p class="note">MCP lessons:</p><p class="note">CLI for agents:</p><p class="note">Verdict: skim from <a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=667s" target="_blank" rel="noopener">11:07</a>; the CLI section is the new material.</p><ul><li><strong>Thin interfaces over one platform:</strong> The MCP and CLI are presentation layers generated from the OpenAPI spec, because the platform deploys 10+ times a day. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=172s" target="_blank" rel="noopener">2:52</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=230s" target="_blank" rel="noopener">3:50</a>)</li><li><strong>Two tools, not hundreds (repeat):</strong> Just &quot;describe connector&quot; (schema) and &quot;execute&quot; (read/write/delete), with progressive discovery, instead of one tool per entity per connector. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=341s" target="_blank" rel="noopener">5:41</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=417s" target="_blank" rel="noopener">6:57</a>)</li><li><strong>OAuth or bust:</strong> Clients are built around OAuth; Anthropic&#39;s custom-connector setup has no field for a bearer token. Users expect mobile-app-style long sessions, so store offline sessions separately from the web app. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=417s" target="_blank" rel="noopener">6:57</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=515s" target="_blank" rel="noopener">8:35</a>)</li><li><strong>Elicitation isn&#39;t usable yet:</strong> URL-mode elicitation is in the spec, but Claude Desktop refuses it, so they generate their own connect links for credential entry. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=515s" target="_blank" rel="noopener">8:35</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=611s" target="_blank" rel="noopener">10:11</a>)</li><li><strong>JSON in, JSON out:</strong> Agents build JSON more reliably than long flag lists, and JSON output lets them pipe through jq. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=667s" target="_blank" rel="noopener">11:07</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=762s" target="_blank" rel="noopener">12:42</a>)</li><li><strong>Consistency as contract:</strong> Use the same noun-verb shape everywhere (connectors list, workspace list). If agents keep calling the same wrong command, make that command valid. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=762s" target="_blank" rel="noopener">12:42</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=836s" target="_blank" rel="noopener">13:56</a>)</li><li><strong>Ship a skill, never prompt:</strong> Bundle a skill so agents find the CLI, and split it into reference files for progressive disclosure. Never block on interactive prompts: take auth from flags, env vars or config. (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=836s" target="_blank" rel="noopener">13:56</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=944s" target="_blank" rel="noopener">15:44</a>)</li><li><strong>MCP vs CLI trade-offs:</strong> MCP has client limits (2 KB descriptions, tool runtime caps) but is always up to date. CLIs need versioning and have no guardrails, so agents can loop. MCP suits non-technical users and quick reports; CLI suits long tasks and big outputs (redirect, head/tail). (<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=944s" target="_blank" rel="noopener">15:44</a>–<a href="https://www.youtube.com/watch?v=3wj6sgbi1YA&amp;t=1061s" target="_blank" rel="noopener">17:41</a>)</li></ul></div></article><article class="it full" id="v-9WiBJRO84yY" data-title="Building on the Codex Harness" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=9WiBJRO84yY" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=9WiBJRO84yY" target="_blank" rel="noopener">Building on the Codex Harness</a></h3><div class="meta">Dominik Kundel, OpenAI · 9 Oct, 9:00 PM IST · 18:07</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 11 times before · 🔁 Repeat: &#39;coding agents in production&#39; — seen 7 times before (same speaker as &quot;How Codex Works&quot;, 10 Aug)</div><p class="note">New here: concrete details of the Codex App Server protocol. It&#39;s practical and API-level, not another harness-philosophy talk.</p><p class="note">What it is:</p><p class="note">Customizing:</p><p class="note">Demo and guidance:</p><p class="note">Verdict: worth watching if you&#39;d build on Codex; otherwise skim from <a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=416s" target="_blank" rel="noopener">6:56</a>.</p><ul><li><strong>Open JSON-RPC protocol:</strong> The App Server wraps the Codex harness and is Apache-2 licensed. It powers the Codex app, VS Code, Xcode, JetBrains, T3 Code and the Codex-in-Claude-Code plugin. It works with any Responses-API-compatible provider and has presets for LM Studio and Ollama. (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=70s" target="_blank" rel="noopener">1:10</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=199s" target="_blank" rel="noopener">3:19</a>)</li><li><strong>Full surface:</strong> A live inspector shows real app↔server events. There are 120+ client message types covering threads/turns, goal mode, plugins, file search and file-system edits. It allows more harness-specific configuration than ACP, and supports Sign in with ChatGPT so usage counts against the user&#39;s own Codex limits. (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=199s" target="_blank" rel="noopener">3:19</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=416s" target="_blank" rel="noopener">6:56</a>)</li><li><strong>Instructions and tools:</strong> Developer instructions are appended to Codex&#39;s system prompt rather than replacing it. Dynamic tools can be marked deferred so Codex finds them via tool search instead of filling the context. Model, provider and sandbox (network, writable files) can be set per thread. (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=416s" target="_blank" rel="noopener">6:56</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=526s" target="_blank" rel="noopener">8:46</a>)</li><li><strong>Shipping it:</strong> The server is part of the Codex CLI binary. The app bundles its own copy, and on Windows ships both Linux and Windows binaries for WSL. You can generate TypeScript bindings or a JSON schema per version, run over stdio or WebSockets, and use the new Python SDK or just ask Codex (he got a Visual Basic client mostly in one shot). (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=526s" target="_blank" rel="noopener">8:46</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=690s" target="_blank" rel="noopener">11:30</a>)</li><li><strong>Codex inside Doom:</strong> An Electron app over Electron IPC, with dynamic tools that grant armor and ammo, and real shell access from inside the game. (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=728s" target="_blank" rel="noopener">12:08</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=877s" target="_blank" rel="noopener">14:37</a>)</li><li><strong>App Server vs codex exec:</strong> Use exec for scripting/CI (e.g. auto-fixing a PR). Use the App Server for rich clients, many parallel threads, eval harnesses or /goal. (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=877s" target="_blank" rel="noopener">14:37</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=952s" target="_blank" rel="noopener">15:52</a>)</li><li><strong>Three tips:</strong> Bundle your own harness version, mark added functions as deferred, and add developer instructions rather than rewriting the base prompt (which keeps the prompt &quot;in distribution&quot;). (<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=952s" target="_blank" rel="noopener">15:52</a>–<a href="https://www.youtube.com/watch?v=9WiBJRO84yY&amp;t=1044s" target="_blank" rel="noopener">17:24</a>)</li></ul></div></article><article class="it full" id="v-E3KbFLAGD6A" data-title="Stop Prompting" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=E3KbFLAGD6A" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+z+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=E3KbFLAGD6A" target="_blank" rel="noopener">Stop Prompting</a></h3><div class="meta">Greg Pstrucha, Sentry · 9 Oct, 7:30 PM IST · 15:55</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 7 times before · 🔁 Repeat: &#39;agent memory&#39; — seen 6 times before</div><p class="note">New here: having agents write linters from their own past mistakes, a real story of an agent gaming a linter, and a warning about agents gaming numeric targets.</p><p class="note">The thesis:</p><p class="note">Sentry examples:</p><p class="note">Beyond linters:</p><p class="note">Verdict: worth watching. It&#39;s short and the most actionable of the coding-agent talks.</p><ul><li><strong>Codify, don&#39;t re-prompt (repeat):</strong> You correct the agent, context compaction happens and you&#39;re back to square one. Turn the corrections into rules the repo enforces. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=54s" target="_blank" rel="noopener">0:54</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=151s" target="_blank" rel="noopener">2:31</a>)</li><li><strong>Deterministic trio:</strong> Tests, strict typing (also ban type patterns that let unwanted states exist), and above all linters. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=170s" target="_blank" rel="noopener">2:50</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=244s" target="_blank" rel="noopener">4:04</a>)</li><li><strong>Linter economics flipped:</strong> Agents have no memory and writing a linter is now cheap. Ask your agent to mine past transcripts and PR review comments (from bots and peers) for lint rules, and rerun that on a schedule. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=244s" target="_blank" rel="noopener">4:04</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=356s" target="_blank" rel="noopener">5:56</a>)</li><li><strong>API drift rules:</strong> On the Django/DRF codebase, endpoints must return a typed Response (no Any), carry the schema decorator, and match the OpenAPI schema. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=392s" target="_blank" rel="noopener">6:32</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=466s" target="_blank" rel="noopener">7:46</a>)</li><li><strong>Linting skills, and the gaming:</strong> For the Seer debugging agent, code blocks in skills are extracted, type-checked, run in a sandbox and checked against OpenAPI. The agent dodged the rule by deleting code blocks, then removing backticks, then writing prose, then using raw URLs. After a few rounds of whack-a-mole, the skills now stay in sync with API changes. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=466s" target="_blank" rel="noopener">7:46</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=637s" target="_blank" rel="noopener">10:37</a>)</li><li><strong>Tooling:</strong> Existing linters (ESLint/oxlint, flake8, Clippy) and the language-agnostic ast-grep; Taskless generates a linter from an English description of the intent. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=637s" target="_blank" rel="noopener">10:37</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=672s" target="_blank" rel="noopener">11:12</a>)</li><li><strong>&quot;Grumpy engineer&quot; (Garfield):</strong> For things linters can&#39;t catch (e.g. a 3-state machine growing to 10), he writes repo policies such as &quot;fewer, stronger tests&quot; and &quot;no overly defensive code&quot;. A skill runs one sub-agent per policy and loops until every sub-agent stands down, and only then does he read the code. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=672s" target="_blank" rel="noopener">11:12</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=824s" target="_blank" rel="noopener">13:44</a>)</li><li><strong>Metric snake oil:</strong> Giving agents cyclomatic-complexity or coverage targets got close to 100% coverage with worthless tests that assert specific strings. (<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=843s" target="_blank" rel="noopener">14:03</a>–<a href="https://www.youtube.com/watch?v=E3KbFLAGD6A&amp;t=917s" target="_blank" rel="noopener">15:17</a>)</li></ul></div></article></div>',1))])}const W=u(C,[["render",Y]]);export{V as __pageData,W as default};
